    def test_remove_calls_with_correct_guild_id(self):
        """remove_player receives the guild's ID, not some other value."""
        cog = lists_cog.Lists(None)
        ctx = self._make_ctx()
        ctx.guild.id = 999999

        with patch('cogs.lists_cog.remove_player', return_value=1) as mock_rm, \
             patch('cogs.lists_cog.load_guild_data', return_value=True):
            _run(cog.deadlist.callback(cog, ctx, "remove", "Test"))

        mock_rm.assert_called_once_with("Test", 999999)

    def test_remove_duplicates_all_deleted(self):
        """When multiple rows exist, all are deleted and rowcount reflects that."""
        cog = lists_cog.Lists(None)
        ctx = self._make_ctx()

        with patch('cogs.lists_cog.remove_player', return_value=3) as mock_rm, \
             patch('cogs.lists_cog.load_guild_data', return_value=True):
            _run(cog.deadlist.callback(cog, ctx, "remove", "JohnDoe"))

        mock_rm.assert_called_once()
        ctx.send.assert_called_once()
        sent = ctx.send.call_args[1].get("content", "") or str(ctx.send.call_args)
        assert "removed from Deadlist" in sent

    def test_remove_no_side_effects_on_not_found(self):
        """When rowcount is 0, the bot does NOT claim removal succeeded."""
        cog = lists_cog.Lists(None)
        ctx = self._make_ctx()

        with patch('cogs.lists_cog.remove_player', return_value=0), \
             patch('cogs.lists_cog.load_guild_data', return_value=True):
            _run(cog.deadlist.callback(cog, ctx, "remove", "GhostPlayer"))

        ctx.send.assert_called_once()
        sent = ctx.send.call_args[1].get("content", "") or str(ctx.send.call_args)
        assert "removed from Deadlist" not in sent
        assert "No deadlist entry" in sent


