class TestDeadlistDisplayFlow:
    """Deep tests for the .d display command."""

    def test_display_calls_get_team_players(self):
        """Display queries all 5 team types."""
        cog = lists_cog.Lists(None)
        ctx = MagicMock()
        ctx.guild.id = 111111
        ctx.send = AsyncMock()

        with patch('cogs.lists_cog.get_team_players', return_value=[]):
            _run(cog.deadlist.callback(cog, ctx))

        ctx.send.assert_called_once()

    def test_display_embed_has_title(self):
        """Display embed has 'Deadlist' title."""
        cog = lists_cog.Lists(None)
        ctx = MagicMock()
        ctx.guild.id = 111111
        ctx.send = AsyncMock()

        with patch('cogs.lists_cog.get_team_players', return_value=[]):
            _run(cog.deadlist.callback(cog, ctx))

        embed = ctx.send.call_args[1]["embed"]
        assert embed.title == "Deadlist"

    def test_display_shows_team_sections(self):
        """Players are grouped by team in the embed."""
        cog = lists_cog.Lists(None)
        ctx = MagicMock()
        ctx.guild.id = 111111
        ctx.send = AsyncMock()

        def mock_get(team, server):
            if team == "village":
                return [("Doctor", "Doctor")]
            elif team == "evil":
                return [("Wolf", "Werewolf")]
            return []

        with patch('cogs.lists_cog.get_team_players', side_effect=mock_get):
            _run(cog.deadlist.callback(cog, ctx))

        embed = ctx.send.call_args[1]["embed"]
        field_names = [f.name for f in embed.fields]
        assert any("Village" in n for n in field_names)
        assert any("Evil" in n for n in field_names)


class TestRemovePlayerRowcount:
    """Deep tests for remove_player returning correct rowcount."""

    def test_returns_integer(self):
        """remove_player returns an integer."""
        from cogs import data_utils
        with patch('cogs.data_utils._bot_db') as mock_db:
            mock_db.remove_player.return_value = 0
            result = data_utils.remove_player("X", 1)
            assert isinstance(result, int)

    def test_passes_through_return_value(self):
        """data_utils wrapper passes bot_db return value through."""
        from cogs import data_utils
        with patch('cogs.data_utils._bot_db') as mock_db:
            mock_db.remove_player.return_value = 5
            assert data_utils.remove_player("X", 1) == 5
        with patch('cogs.data_utils._bot_db') as mock_db:
            mock_db.remove_player.return_value = 0
            assert data_utils.remove_player("X", 1) == 0
        with patch('cogs.data_utils._bot_db') as mock_db:
            mock_db.remove_player.return_value = 1
            assert data_utils.remove_player("X", 1) == 1

    def test_edit_calls_remove_then_add(self):
        """Edit flow removes first, then adds — in that order."""
        call_order = []
        cog = lists_cog.Lists(None)
        ctx = MagicMock()
        ctx.author.guild_permissions.administrator = True
        ctx.guild.get_member.return_value = None
        ctx.guild.id = 777
        ctx.send = AsyncMock()

        def track_remove(*a, **kw):
            call_order.append("remove")
            return 1

        def track_add(*a, **kw):
            call_order.append("add")

        with patch('cogs.lists_cog.remove_player', side_effect=track_remove), \
             patch('cogs.lists_cog.add_player', side_effect=track_add), \
             patch('cogs.lists_cog.load_guild_data', return_value=True):
            _run(cog.deadlist.callback(cog, ctx, "edit", "JohnDoe", "village", role="Doc"))

        assert call_order == ["remove", "add"]
